package com.crewbeat.hondabox.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import com.crewbeat.hondabox.*;
/** Actual callbacks, BSJ decoder and Debug views; no hardware or commands. */
public final class RadioDebugTests extends Instrumentation {
 private final ProbeState state=ProbeState.INSTANCE;private Activity activity;private int checks;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 private void frame(int type,int... p){int[] a=new int[p.length+4];a[0]=46;a[1]=type;a[2]=p.length;int sum=type+p.length;for(int i=0;i<p.length;i++){a[i+3]=p[i];sum+=p[i];}a[a.length-1]=255-(sum&255);state.event(1019,a,null,null);}
 private void text(int kind,String value){int[] p=new int[value.length()+1];p[0]=kind;for(int i=0;i<value.length();i++)p[i+1]=value.charAt(i);frame(7,p);}
 private void event(int code,int value){state.event(code,new int[]{value},null,null);}
 private void callback(int code,String text){state.event(code,null,null,new String[]{text});}
 private void render(){runOnMainSync(()->{try{java.lang.reflect.Method m=SettingsScreenActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();}
 private void image(Context c,String tag,String name)throws Exception{View value=activity.findViewById(android.R.id.content).findViewWithTag(tag);java.lang.reflect.Field f=SettingsScreenActivity.class.getDeclaredField("scroll");f.setAccessible(true);ScrollView scroll=(ScrollView)f.get(activity);runOnMainSync(()->{android.graphics.Rect r=new android.graphics.Rect();value.getDrawingRect(r);scroll.offsetDescendantRectToMyCoords(value,r);scroll.scrollTo(0,Math.max(0,r.top-100));});SystemClock.sleep(500);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Override public void onStart(){Context c=getTargetContext();String lang=I18n.language(c),theme=ThemeSettings.mode(c);boolean recording=state.recording();Bundle result=new Bundle();int outcome=Activity.RESULT_OK;
  try{c.stopService(new Intent(c,ProbeService.class));SystemClock.sleep(300);I18n.language(c,"en");state.newSession();state.running(true);state.recording(false);state.status("test","local radio fixture",true);event(1000,6291908);event(98,2);callback(104,"Old album");event(98,1);event(115,1);event(119,241);event(118,0);frame(4,2,0,251,0,0x81);
   String fields=RadioDebugInfo.fields(state.snapshot());for(int code=115;code<=125;code++)check(fields.contains("["+code+"]"),"radio field "+code+" present");check(fields.contains("CAN [1]")&&fields.contains("BSJ [2]"),"callback and BSJ band remain separate");check(fields.contains("100.00 MHz")&&fields.contains("ST ON")&&fields.contains("Normal"),"fresh decoded frequency and status");check(fields.contains("[0]"),"zero retained as an actual value");check(fields.contains("CAN —")&&fields.contains("BSJ —"),"missing field has no fake value");
   String old=RadioDebugInfo.textChannels(state.snapshot());check(old.contains("Old album")&&old.contains("before source change"),"old media text remains marked as older source");text(1,"TEXT CANDIDATE");text(5,"file text");text(6,"extra album");callback(135,"AF ON\0");callback(136,"");String texts=RadioDebugInfo.textChannels(state.snapshot());for(int code:new int[]{103,104,105,135,136,137})check(texts.contains("["+code+"]"),"text channel "+code+" present");check(texts.contains("TEXT CANDIDATE")&&texts.contains("07/05")&&texts.contains("file text")&&texts.contains("extra album"),"BSJ text channels visible");check(texts.contains("AF ON\\0")&&texts.contains("\"\""),"control byte and empty string are explicit");
   frame(4,2,1,15,3,0x80);fields=RadioDebugInfo.fields(state.snapshot());check(fields.contains("[122]")&&fields.contains("BSJ [271]")&&fields.contains("101.00 MHz"),"preset data decoded");event(98,2);fields=RadioDebugInfo.fields(state.snapshot());check(!fields.contains("101.00 MHz")&&fields.contains("before source change"),"inactive old radio data is not decoded as current");event(98,1);frame(4,4,0,9,0,1);fields=RadioDebugInfo.fields(state.snapshot());check(fields.contains("AM1 / MW")&&fields.contains("603 kHz"),"AM values use kHz");
   callback(103,"Text candidate (test)");activity=startActivitySync(new Intent(c,DebugActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(String language:new String[]{"en","ru"})for(String appearance:new String[]{ThemeSettings.DAY,ThemeSettings.NIGHT}){I18n.language(c,language);ThemeSettings.mode(c,appearance);render();TextView radio=activity.findViewById(android.R.id.content).findViewWithTag("debug-radio-fields"),text=activity.findViewById(android.R.id.content).findViewWithTag("debug-radio-text");check(radio!=null&&text!=null&&radio.isTextSelectable()&&text.isTextSelectable(),"selectable diagnostic views");check(radio.getText().toString().equals(RadioDebugInfo.fields(state.snapshot()))&&text.getText().toString().equals(RadioDebugInfo.textChannels(state.snapshot())),"live diagnostic views update");check(!state.recording(),"no recording needed for latest fields");if(language.equals("en")){image(c,"debug-radio-fields","radio-debug-"+appearance+"-TEST.png");image(c,"debug-radio-text","radio-text-debug-"+appearance+"-TEST.png");}}
   state.status("test","disconnected",false);render();fields=RadioDebugInfo.fields(state.snapshot());check(fields.contains(I18n.t(R.string.debug_radio_history))&&fields.contains("BSJ [9]")&&!fields.contains(" → "),"disconnected data is explicitly historical and undecoded");
   result.putString("result","PASS: "+checks+" radio diagnostics checks");
  }catch(Throwable e){outcome=1;result.putString("failure",android.util.Log.getStackTraceString(e));}finally{if(activity!=null)runOnMainSync(()->activity.finish());waitForIdleSync();state.newSession();state.running(false);state.recording(recording);I18n.language(c,lang);ThemeSettings.mode(c,theme);}finish(outcome,result);
 }
}
